import { tags } from "typia";

import { IEcommerceMallNotification } from "./IEcommerceMallNotification";

/**
 * Notification dashboard summary providing an at-a-glance view of notification status for the authenticated admin actor. Includes unread notification count, category breakdowns, recent notifications list, and optional system-wide alert status. This dashboard view enables administrators to quickly assess notification engagement and identify urgent system alerts without querying individual notification records.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEcommerceMallNotificationDashboard = {
  /**
   * Total count of unread notifications for this admin
   *
   * @x-autobe-specification Computed: COUNT(*) of notifications where status='unread' for this admin actor. Aggregation: SELECT COUNT(*) FROM ecommerce_mall_notifications n JOIN ecommerce_mall_notification_of_admins aoa ON n.id = aoa.notification_id WHERE aoa.admin_id=[current_admin_id] AND n.status='unread'.
   */
  unreadCount: number & tags.Type<"int32">;

  /**
   * The 10 most recent notifications with read status
   *
   * @x-autobe-specification Computed: SELECT n.id, n.title, n.body, n.type, n.status, n.created_at FROM ecommerce_mall_notifications n JOIN ecommerce_mall_notification_of_admins aoa ON n.id = aoa.notification_id WHERE aoa.admin_id=[current_admin_id] ORDER BY n.created_at DESC LIMIT 10. Returns IEcommerceMallNotification.ISummary objects.
   */
  recentNotifications: IEcommerceMallNotification.ISummary[] &
    tags.MaxItems<10>;

  /**
   * Summary total of unread notifications across all categories
   *
   * @x-autobe-specification Computed: COUNT(*) FILTER (WHERE status='unread') from ecommerce_mall_notifications table. This is the aggregate unread count for the admin actor, including all notification categories (platform_announcements, system_alerts, order_updates, seller_notifications, etc.).
   */
  totalUnread: number & tags.Type<"int32">;

  /**
   * System-wide alert status if any active platform announcements exist
   *
   * @x-autobe-specification Computed: Check if any notifications exist with type='platform_announcement' or type='system_alert' and status='unread' for this admin actor. Set hasAlert=true if such notifications exist. alertLevel determined by priority rules: critical > warning > info.
   */
  systemAlert?:
    | {
        /**
         * Whether there is an active system-wide alert
         */
        hasAlert: boolean;

        /**
         * Optional system alert message if one exists
         */
        alertMessage?: string | undefined;

        /**
         * Priority level of the system alert
         */
        alertLevel?: "info" | "warning" | "critical" | undefined;
      }
    | undefined;
};
